import {evidenceIndex,resolveFact} from './narrative-evidence.js';
import {factText} from './narrative-memory-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function chapterEvidenceHTML(state,chapter){
 const index=evidenceIndex(state);
 return `<details class="chapter-evidence"><summary>Chapter evidence · ${chapter.threads.length} selected thread${chapter.threads.length===1?'':'s'}</summary><p class="small-note">Saved ${esc(chapter.templateId)} · version ${chapter.version} · closing incident ${esc(chapter.closureIncidentId)}. Factual sources and personal interpretations remain distinct. The chronological journal is retained separately.</p>${chapter.threads.map(t=>`<section><h5>${esc(t.templateId)}${t.parameters.person?' · '+esc(t.parameters.person):''}</h5><ul>${t.clauses.map(c=>`<li>${esc(c.text)}<small> ${c.evidence.map(r=>esc(r.incidentId+'/'+r.factKey)).join(', ')}${c.memoryIds.length?' · memories '+c.memoryIds.map(esc).join(', '):''}</small></li>`).join('')}</ul><p>State at the saved close: ${esc(t.endState.region)}${t.endState.control?' · '+esc(t.endState.control)+' control':''}${t.endState.orderId?' · opportunity '+esc(t.endState.orderId)+' '+(t.endState.available?'available':'disrupted'):''}.</p>${t.evidence.map(ref=>{const source=resolveFact(index,ref);return source?`<details><summary>Source · Turn ${source.entry.turn}: ${esc(source.entry.title)}</summary><p>${esc(factText(source.fact))}</p><small>${esc(ref.incidentId)} · ${esc(ref.factKey)}</small></details>`:'';}).join('')}${t.memoryIds.map(id=>{const m=state.narrative.memories[id];return `<p><b>Owned personal interpretation · ${esc(state.narrative.characters[m.ownerId].name)}</b>: ${esc(m.interpretation.text)}</p>`;}).join('')}${t.reasonRefs.map(ref=>{const cause=state.narrative.characters[ref.ownerId].relations[ref.target].causes.find(c=>c.id===ref.causeId);return `<p><b>Saved relationship reason · personal judgment</b>: ${esc(cause.reason)}</p>`;}).join('')}${t.lineIds.map(id=>{const source=index.lines.get(id);return `<blockquote><b>${esc(source.line.speaker)}</b><p>${esc(source.line.text)}</p><small>Saved words · ${esc(id)}</small></blockquote>`;}).join('')}</section>`).join('')}</details>`;
}
